def params_from_uri(uri):
    params = {}
    parsed = urlparse(uri)
    pairs = urldecode(parsed.query)
    for k, v in pairs:
        if k in params:
            if isinstance(params[k], list):
                params[k].append(v)
            else:
                params[k] = [params[k], v]
        else:
            params[k] = v
    # Handle scope specially - split by space
    if 'scope' in params:
        scope = params['scope']
        if isinstance(scope, str):
            params['scope'] = scope_to_list(scope)
    return params
